	day VARCHAR(10) NOT NULL, 
	type VARCHAR(32) NOT NULL, 
	owner_id VARCHAR(80), 
	ip_hash VARCHAR(16), 
	data JSONB NOT NULL, 
	PRIMARY KEY (id)
